    "dil.son_sefer.r0": "Hisse ödendi; hanenin adı seferin defterine yazıldı.",
    "dil.son_sefer.r1": "Evladın yola çıktı; hane bir yıl duayla yaşadı. Dönünce ocağa başka gözle baktı.",
    "dil.son_sefer.r2": "Beyin kâtibi adını not etti; kasaba buna kimi zaman ihtiyat, kimi zaman korku dedi.",
    "dil.son_sefer.t": "Sefer Hissesi",
    "dil.son_sefer.x": "Sefere çıkan beylik hanelerden hisse istiyor: ya kese ya er.",
    "dil.son_soz.t": "Son Söz",
    "dil.son_vakif.c0": "Çeşme yaptır",
    "dil.son_vakif.c1": "Aşevi aç",
    "dil.son_vakif.c2": "Taş bir başka bahara",
    "dil.son_vakif.r0": "Çeşmenin taşına hanenin adı kazındı; su akarken evlatlar da durup okudu.",
    "dil.son_vakif.r1": "Aşevi kapısını açtı; o kış kasabada aç yatan olmadı.",
    "dil.son_vakif.r2": "Ustaya kaparoyu geri aldırdın; taş avluda, yosun tutarak bekliyor.",
    "dil.son_vakif.t": "Vakıf Taşı",
    "dil.son_vakif.x": "Bir vakıf kurmayı düşünüyorsun: çeşme mi, aşevi mi? Kese azalır, ad kalır.",
    "dil.son_vasiyet.c0": "İlk doğana",
    "dil.son_vasiyet.c1": "Ocağa en çok emek verene",
    "dil.son_vasiyet.c2": "Eşit paylara",
    "dil.son_vasiyet.r0": "Töre yolunu seçtin; büyük evlat başını eğdi, küçükler sustu.",
    "dil.son_vasiyet.r1": "Eli en çok ocağa değene yazdın; meşru ama tartışmalı bir karar.",
    "dil.son_vasiyet.r2": "Ocağı paylara böldün; kavga çıkmadı, ama ocak da küçüldü.",
    "dil.son_vasiyet.t": "Vasiyetin Satırı",
    "dil.son_vasiyet.x": "Kadı vasiyetin taslağını getirdi. Bir satır boş: ocak kimin elinde kalacak?",
