    "kronik.yaylar": "Tamamlanan hikâyeler: %1/%2",
    "kronik.yetenek": "Bıraktığı yetenek: %1",
    "new.soy.not": "Defter ve tek soy yeteneği geçer; para, mülk ve itibar geçmez.",
    "new.soy.sub": "%1 hanesi · %2. kuşak · son ata: %3",
    "new.soy.title": "Soyu sürdür",
    "new.soy.yeni": "Yeni bir soy başlat",
    "not.borc": "Tefecinin faizi her ay büyüyor: borç %1 akçe.",
    "not.evlat16": "%1 gelecek yıl on altısına basıyor.",
    "not.hasat": "Gelecek ay hasat: tarlanın emeği toplanacak.",
    "not.ip": "Akılda bir soru: %1.",
    "not.ipYakin": "Vakti yaklaşıyor: %1.",
    "not.kisBos": "Kış kapıda, kiler boş.",
    "not.kisDolu": "Kış kapıda; kiler dolu, gönül rahat.",
    "not.rakip": "%1 ile lonca bayrağı yarışı yaklaşıyor.",
    "not.senlik": "Gelecek ay şenlik var; kasaba şimdiden hazırlanıyor.",
    "not.sinav": "Ustaların yeniden sınava çağırmasına %1 ay var.",
    "ocak.alt": "Ardında vâris kalmadı, ama defter yanmadı. Aynı soyadla yeni bir hayat başlar: atanın en çok anılan kararları kasabada yankılanır.",
    "ocak.ata": "Ata: %1 · %2. nesil",
    "ocak.basla": "Ocağı yak",
    "ocak.cins": "YENİ HAYAT",
    "paylas.metin": "ya da metin olarak paylaş",
    "ritim.bayram": "Dışarıda bayram: kasabada da kapılar açık, büyüklerin eli öpülüyor, şeker dağıtılıyor.",
    "ritim.esitlik": "Dışarıda gece ile gündüz eşitlendi; kasabada harman türküleri söyleniyor.",
    "ritim.gundonumu": "Dışarıda yılın en uzun günü; kasaba gölgede oturup akşamı bekliyor.",
    "ritim.hidrellez": "Dışarıda Hıdrellez: kasabada gül dallarına dilek bağlanıyor.",
    "ritim.ilkbahar.0": "Dışarıda bahar; kasabada da erik çiçek açtı.",
    "ritim.ilkbahar.1": "Dışarıda bahar yağmuru; çarşı çamurlu ama neşeli.",
    "ritim.kis.0": "Dışarıda kış; kasabanın bacaları da tütüyor.",
    "ritim.kis.1": "Dışarıda soğuk; hikâyeler ocak başında daha iyi anlatılır.",
    "ritim.nevruz": "Dışarıda Nevruz: kasabada da ateş yakılmış, gençler üstünden atlıyor.",
    "ritim.sonbahar.0": "Dışarıda güz; kasabada kışlık hazırlığı başladı.",
    "ritim.sonbahar.1": "Dışarıda yapraklar dökülüyor; kervanlar son yollarına çıkıyor.",
    "ritim.yalda": "Dışarıda yılın en uzun gecesi; ocak başında nar kesiliyor, masallar anlatılıyor.",
    "ritim.yaz.0": "Dışarıda yaz; kasabada çeşme başında sıra var.",
    "ritim.yaz.1": "Dışarıda uzun günler; çocuklar akşama dek sokakta.",
    "ritim.yilbasi": "Dışarıda yeni bir yıl başlıyor; kasabanın kâtibi de defterine taze bir sayfa açtı.",
