    "seed.velinimetFakir": "Yıllar önce derdine omuz verdiğin %1 hiç belini doğrultamadı; ödeyecek bir şeyi yok, ama her bayram kapına bir avuç kuru üzümle geliyor.",
    "soy.carsi_dili.ad": "Çarşı Dili",
