    "soy.pehlivan_kani.ad": "Pehlivan Kanı",
    "soy.pehlivan_kani.arti": "Bir puan fazla güç",
    "soy.pehlivan_kani.bedel": "Bir puan eksik karizma",
    "soy.sec.alt": "Tek bir yetenek seçilir; her birinin bir bedeli var. Para ve mülk geçmez, yalnız soyun izi geçer.",
    "soy.sec.baslik": "SOYDAN NE KALSIN?",
    "soy.yok": "Yetenek yok, temiz sayfa",
