    "ritim.bayram": "Outside it is a holiday: in town the doors stand open, elders' hands are kissed, sweets are handed out.",
    "ritim.esitlik": "Outside, night and day are equal; threshing songs are sung in town.",
    "ritim.gundonumu": "Outside it is the longest day of the year; the town sits in the shade and waits for evening.",
    "ritim.hidrellez": "Outside it is Hıdrellez: in town wishes are tied to rose branches.",
    "ritim.ilkbahar.0": "Outside it is spring; the plum trees in town have blossomed too.",
    "ritim.ilkbahar.1": "Outside, spring rain; the bazaar is muddy but merry.",
    "ritim.kis.0": "Outside it is winter; the town's chimneys are smoking too.",
    "ritim.kis.1": "Outside it is cold; stories are best told by the hearth.",
    "ritim.nevruz": "Outside it is Nowruz: in town a fire is lit and the young leap over it.",
    "ritim.sonbahar.0": "Outside it is autumn; the town has begun preparing for winter.",
    "ritim.sonbahar.1": "Outside the leaves are falling; caravans set out on their last roads.",
    "ritim.yalda": "Outside it is the longest night of the year; by the hearth pomegranates are cut and tales are told.",
    "ritim.yaz.0": "Outside it is summer; in town there is a queue at the fountain.",
    "ritim.yaz.1": "Outside, long days; children stay in the street until evening.",
    "ritim.yilbasi": "Outside, a new year begins; the town scribe has opened a fresh page in his ledger too.",
    "roman.acilis": "%1 lived %2 years.",
    "roman.acilis.sag": "%1 is only %2; the story goes on.",
