    "soy.gonul_eli.bedel": "Slower progress in combat",
    "soy.hayir_ocagi.ad": "House of Charity",
    "soy.hayir_ocagi.arti": "Higher reputation at the start",
    "soy.hayir_ocagi.bedel": "Slower progress in trade",
    "soy.kalem_ehli.ad": "Man of Letters",
    "soy.kalem_ehli.arti": "One extra point of intelligence",
    "soy.kalem_ehli.bedel": "One point less strength",
    "soy.kilic_yemini.ad": "Sword Oath",
    "soy.kilic_yemini.arti": "Faster progress in combat",
    "soy.kilic_yemini.bedel": "Slower progress in conversation",
    "soy.kul": "A new hearth was lit from the ashes. The ledger of the %1 line is not closed; the town still speaks that name.",
    "soy.miras": "A talent from the bloodline passed into this life: %1.",
    "soy.ocak_eli.ad": "Hearth Hand",
    "soy.ocak_eli.arti": "Faster progress in crafting",
    "soy.ocak_eli.bedel": "Slightly less reputation at the start",
