    "soy.pehlivan_kani.arti": "One extra point of strength",
    "soy.pehlivan_kani.bedel": "One point less charisma",
    "soy.sec.alt": "Only one talent is chosen, and each has a cost. Money and property do not pass on; only the mark of the line does.",
    "soy.sec.baslik": "WHAT SHOULD THE LINE KEEP?",
    "soy.yok": "No talent, a clean page",
    "soy.yol_kani.ad": "Road Blood",
