    "ritim.bayram": "Fuera es fiesta: en el pueblo las puertas están abiertas, se besa la mano a los mayores y se reparten dulces.",
    "ritim.esitlik": "Fuera, la noche y el día se igualan; en el pueblo se cantan canciones de trilla.",
    "ritim.gundonumu": "Fuera es el día más largo del año; el pueblo espera la tarde a la sombra.",
    "ritim.hidrellez": "Fuera es Hıdrellez: en el pueblo atan deseos a las ramas de rosal.",
    "ritim.ilkbahar.0": "Fuera es primavera; en el pueblo también florecieron los ciruelos.",
    "ritim.ilkbahar.1": "Fuera, lluvia de primavera; el bazar está embarrado pero alegre.",
    "ritim.kis.0": "Fuera es invierno; las chimeneas del pueblo también humean.",
    "ritim.kis.1": "Fuera hace frío; las historias se cuentan mejor junto al hogar.",
    "ritim.nevruz": "Fuera es Nouruz: en el pueblo encendieron una hoguera y los jóvenes saltan sobre ella.",
    "ritim.sonbahar.0": "Fuera es otoño; el pueblo empezó a prepararse para el invierno.",
    "ritim.sonbahar.1": "Fuera caen las hojas; las caravanas emprenden sus últimos caminos.",
    "ritim.yalda": "Fuera es la noche más larga del año; junto al hogar se cortan granadas y se cuentan cuentos.",
    "ritim.yaz.0": "Fuera es verano; en el pueblo hay cola en la fuente.",
    "ritim.yaz.1": "Fuera, días largos; los niños siguen en la calle hasta la noche.",
    "ritim.yilbasi": "Fuera empieza un año nuevo; el escribano del pueblo también abrió una página nueva en su libro.",
