    "seed.velinimetFakir": "%1, a quien apoyaste hace años, nunca logró levantarse; no tiene con qué pagar, pero cada día de fiesta viene a tu puerta con un puñado de pasas.",
    "soy.carsi_dili.ad": "Lengua de Bazar",
