    "yanki.arc.celiski": "A decisão tomada em «%1» surpreendeu quem conhece o dia de «%2»; durante algum tempo o teu nome foi dito de duas maneiras.",
    "yanki.arc.tutarli": "Ao longo de «%1» a vila viu-te seguir o caminho pelo qual te conhecia: era a pessoa do dia de «%2». A notícia correu depressa; a estima subiu.",
