    "yanki.ata.comert.1": "A mão que o teu antepassado %1 estendeu no dia de «%2» voltou hoje para ti no cumprimento de um neto.",
    "yanki.ata.durust.0": "A honestidade do teu antepassado %1 no dia de «%2» anda na boca da vila; graças a ela, a tua palavra vale sem promissória.",
    "yanki.ata.durust.1": "Um velho contou o dia de «%2»: 'O teu antepassado %1 era dessa gente; vamos ver como és tu.'",
    "yanki.ata.hile.0": "O dia de «%2» do teu antepassado %1 não foi esquecido; uma sombra cai sobre o teu nome no bazar.",
    "yanki.ata.hile.1": "Alguém que conhece o dia de «%2» lembrou-te a dívida do teu antepassado %1; não é a tua dívida, mas é o teu fardo.",
    "yanki.ata.hirs.0": "As contas do teu antepassado %1 no dia de «%2» ainda dão que falar; um lojista manteve distância de ti.",
    "yanki.ata.hirs.1": "Alguém que se lembra do dia de «%2» perguntou-te pelo teu antepassado %1 e foi-se sem esperar resposta.",
    "yanki.ata.temkin.0": "A paciência do teu antepassado %1 no dia de «%2» tornou-se a ordem da lareira; os velhos julgam-te igualmente comedido.",
    "yanki.ata.temkin.0.f": "A paciência do teu antepassado %1 no dia de «%2» tornou-se a ordem da lareira; os velhos julgam-te igualmente comedida.",
    "yanki.ata.temkin.1": "Um vizinho contou o dia de «%2»: 'O teu antepassado %1 não gostava de pressas; por isso a lareira ficou firme.'",
    "yanki.celiski": "Quem se lembra do dia de «%1» ficou surpreendido: esta decisão não parecia daquela pessoa. Alguns voltaram a olhar para ti.",
    "yanki.cesur.0": "No dia de «%1» não se deu um passo atrás. Hoje os rapazes contaram essa história à tua frente, um pouco aumentada.",
    "yanki.cesur.1": "Um viajante ouviu a história de «%1» noutra vila; o teu nome chegou lá antes de ti.",
    "yanki.cesur.2": "Desde o dia de «%1», o guarda-noturno endireita-se para te cumprimentar.",
    "yanki.comert.0": "No dia de «%1» meteste mãos à obra. Hoje alguém no bazar lembrou-se disso e falou a teu favor.",
    "yanki.comert.1": "Alguém que não esqueceu o dia de «%1» deixou um cesto à tua porta, com um bilhete: 'Naquele dia, deste.'",
    "yanki.comert.2": "Uma criança do bairro contava a história de «%1»; o herói eras tu.",
    "yanki.durust.0": "No dia de «%1» não se largou o caminho certo. Hoje, quando foi preciso uma testemunha num processo, o teu nome foi o primeiro.",
    "yanki.durust.1": "Um mercador estrangeiro entregou mercadoria só pela tua palavra: 'Ouvi a história de «%1»; não preciso de promissória.'",
    "yanki.durust.2": "O dia de «%1» continua na memória da vila: numa disputa, ambas as partes te indicaram como árbitro.",
