    "yanki.temkin.0": "No dia de «%1» escolheu-se a prudência. Hoje, ao ver como voltaram os que seguiram aquele caminho, passou-te por dentro um agradecimento.",
    "yanki.temkin.1": "A paciência do dia de «%1» deu fruto hoje: sem pressas, sem dívidas, corpo são.",
