    "ocak.alt": "Наследника не осталось, но книга не сгорела. Новая жизнь начинается под той же фамилией: самые памятные решения предка отзываются в городе.",
    "ocak.ata": "Предок: %1 · поколение %2",
    "ocak.basla": "Зажечь очаг",
    "ocak.cins": "НОВАЯ ЖИЗНЬ",
    "paylas.metin": "или поделиться текстом",
    "ritim.bayram": "Снаружи праздник: в городе двери открыты, старшим целуют руки, раздают сладости.",
    "ritim.esitlik": "Снаружи ночь сравнялась с днём; в городе поют песни молотьбы.",
    "ritim.gundonumu": "Снаружи самый длинный день в году; город сидит в тени и ждёт вечера.",
    "ritim.hidrellez": "Снаружи Хыдырлез: в городе к ветвям шиповника привязывают желания.",
    "ritim.ilkbahar.0": "Снаружи весна; в городе тоже зацвели сливы.",
    "ritim.ilkbahar.1": "Снаружи весенний дождь; на базаре грязно, но весело.",
    "ritim.kis.0": "Снаружи зима; трубы в городе тоже дымят.",
    "ritim.kis.1": "Снаружи холодно; истории лучше рассказывать у очага.",
    "ritim.nevruz": "Снаружи Навруз: в городе развели костёр, и молодёжь прыгает через него.",
    "ritim.sonbahar.0": "Снаружи осень; город начал готовиться к зиме.",
    "ritim.sonbahar.1": "Снаружи падают листья; караваны выходят в последние дороги.",
    "ritim.yalda": "Снаружи самая длинная ночь в году; у очага режут гранаты и рассказывают сказки.",
    "ritim.yaz.0": "Снаружи лето; в городе очередь у фонтана.",
    "ritim.yaz.1": "Снаружи длинные дни; дети до вечера на улице.",
    "ritim.yilbasi": "Снаружи начинается новый год; городской писарь тоже открыл в книге свежую страницу.",
    "roman.acilis": "%1: прожито лет — %2.",
