    "scr.divan": "Диван",
    "scr.kronik": "Хроника",
    "scr.ocak": "Новый очаг из пепла",
    "seed.velinimetFakir": "%1, кого когда-то поддержали в беде, так и не встал на ноги; отплатить нечем, но в каждый праздник у твоей двери появляется горсть изюма.",
    "soy.carsi_dili.ad": "Язык базара",
    "soy.carsi_dili.arti": "Торговля растёт быстрее",
    "soy.carsi_dili.bedel": "Чуть меньше чести в начале",
