    "soy.hayir_ocagi.bedel": "Торговля растёт медленнее",
    "soy.kalem_ehli.ad": "Люди пера",
    "soy.kalem_ehli.arti": "Плюс одно очко интеллекта",
    "soy.kalem_ehli.bedel": "Минус одно очко силы",
    "soy.kilic_yemini.ad": "Клятва меча",
    "soy.kilic_yemini.arti": "Бой растёт быстрее",
    "soy.kilic_yemini.bedel": "Беседа растёт медленнее",
    "soy.kul": "Из пепла зажжён новый очаг. Книга рода не закрыта: имя %1 в городе всё ещё помнят.",
    "soy.miras": "Дар рода перешёл в эту жизнь: %1.",
    "soy.ocak_eli.ad": "Рука очага",
    "soy.ocak_eli.arti": "Ремесло растёт быстрее",
    "soy.ocak_eli.bedel": "Чуть меньше репутации в начале",
    "soy.pehlivan_kani.ad": "Кровь борца",
    "soy.pehlivan_kani.arti": "Плюс одно очко силы",
    "soy.pehlivan_kani.bedel": "Минус одно очко обаяния",
    "soy.sec.alt": "Выбирается лишь один дар, и у каждого есть цена. Деньги и имущество не передаются, только след рода.",
    "soy.sec.baslik": "ЧТО СОХРАНИТ РОД?",
    "soy.yok": "Без дара, чистый лист",
    "soy.yol_kani.ad": "Кровь дороги",
    "soy.yol_kani.arti": "Плюс одно очко выносливости",
    "soy.yol_kani.bedel": "Ремесло растёт медленнее",
    "yanki.arc.celiski": "Решение, принятое в истории «%1», удивило тех, кто знает день «%2»; какое-то время твоё имя звучало по-разному.",
    "yanki.arc.tutarli": "Всю историю «%1» городок видел тебя на той дороге, по которой знал: это был человек дня «%2». Молва разошлась быстро, уважение выросло.",
    "yanki.ata.cesur.0": "Отвага твоего предка %1 в день «%2» вошла в песни; молодёжь просит тебя рассказать.",
    "yanki.ata.cesur.1": "В день «%2» твой предок %1 не отступил; сегодня на площади кто-то вспомнил об этом при тебе.",
    "yanki.ata.comert.0": "Щедрость твоего предка %1 в день «%2» не забыта: старик открыл тебе дверь ради памяти о нём.",
    "yanki.ata.comert.1": "Рука, протянутая твоим предком %1 в день «%2», вернулась сегодня к тебе приветствием внука.",
    "yanki.ata.durust.0": "Честность твоего предка %1 в день «%2» у городка на устах; благодаря ей твоё слово проходит без расписки.",
    "yanki.ata.durust.1": "Старик рассказал о дне «%2»: «Твой предок %1 был из таких; посмотрим, каков ты.»",
    "yanki.ata.durust.1.f": "Старик рассказал о дне «%2»: «Твой предок %1 был из таких; посмотрим, какова ты.»",
    "yanki.ata.hile.0": "День «%2» твоего предка %1 не забыт; на твоё имя на базаре падает тень.",
    "yanki.ata.hile.1": "Кто-то, знающий день «%2», напомнил тебе о долге предка %1; долг не твой, но ноша твоя.",
